/// FreeANDIY's look on upstream's tokens for brightness `b`.
pub fn tokens(b: Brightness, t: Tokens) -> Tokens {
    if b == Brightness::HighContrast {
        return t;
    }
    let t = Tokens { radius: 0, accent: if t.dark { PINK } else { ROSE }, accent_strong: ROSE, ..t };
    match b {
        Brightness::Dark => {
            let ink = |x: f32| mix(BLACK, PAPER, x);
            Tokens {
                app_bar: BLACK,
                panel: mix(BLACK, PAPER, 0.06),
                panel_darker: BLACK,
                tab_strip: BLACK,
                input: mix(BLACK, Color32::BLACK, 0.30),
                input_border: ink(0.30),
                divider: ink(0.16),
                text: ink(0.88),
                text_strong: PAPER,
                text_dim: ink(0.66),
                text_disabled: ink(0.40),
                icon: ink(0.85),
                hover: ink(0.16),
                tool_active: mix(BLACK, Color32::BLACK, 0.40),
                row_selected: mix(BLACK, ROSE, 0.45),
                button: ink(0.14),
                ..t
            }
        }
        Brightness::Light => {
            let ink = |x: f32| mix(PAPER, BLACK, x);
            Tokens {
                app_bar: ink(0.06),
                panel: PAPER,
                panel_darker: ink(0.05),
                tab_strip: ink(0.08),
                input: WHITE,
                input_border: ink(0.30),
                divider: ink(0.15),
                text: BLACK,
                text_strong: BLACK,
                text_dim: ink(0.70),
                text_disabled: ink(0.45),
                icon: BLACK,
                hover: ink(0.08),
                tool_active: ink(0.16),
                row_selected: mix(PAPER, YELLOW, 0.60),
                button: ink(0.08),
                ..t
            }
        }
        _ => t,
    }
}

/// Flat print look for egui's own surfaces: nearly square windows and menus, no soft shadows.
pub fn visuals(v: &mut Visuals) {
    v.window_corner_radius = egui::CornerRadius::same({{shape.radius_sm}});
    v.menu_corner_radius = egui::CornerRadius::same({{shape.radius_sm}});
    v.popup_shadow = egui::epaint::Shadow::NONE;
    v.window_shadow = egui::epaint::Shadow::NONE;
}

/// An embedded PNG as a mipmapped texture, decoded once per context.
fn png_texture(ctx: &Context, name: &str, bytes: &[u8]) -> Option<TextureHandle> {
    let id = Id::new(name);
    if let Some(tex) = ctx.data(|d| d.get_temp::<TextureHandle>(id)) {
        return Some(tex);
    }
    let pm = designcraft_render::decode_pixmap_page(bytes, 0)?;
    let image = egui::ColorImage::from_rgba_premultiplied([pm.width() as usize, pm.height() as usize], pm.data_as_u8_slice());
    let options = TextureOptions { mipmap_mode: Some(egui::TextureFilter::Linear), ..TextureOptions::LINEAR };
    let tex = ctx.load_texture(name, image, options);
    ctx.data_mut(|d| d.insert_temp(id, tex.clone()));
    Some(tex)
}

const MARK_PNG: &[u8] = include_bytes!("../../../assets/app-icon/{{this.repo}}-mark.png");
const SEAL_PNG: &[u8] = include_bytes!("../../../freeandiy/assets/brand/fa-seal-rose.png");

/// Paint the app's mark (its monogram tile) into `rect`.
pub fn paint_mark(ui: &Ui, rect: Rect) {
    if let Some(tex) = png_texture(ui.ctx(), "freeandiy-mark", MARK_PNG) {
        ui.painter().image(tex.id(), rect, Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(1.0, 1.0)), Color32::WHITE);
    }
}

/// English, like upstream's credits; the Slovak table translates it.
const ATTRIBUTION: &str = "{app} is based on the open-source project {upstream} (© ArtCraft Team and contributors, MIT/Apache-2.0). FreeANDIY is not affiliated with the ArtCraft team.";

/// The About splash's attribution: the Free Andy Agency seal and the upstream credit
/// (MIT/Apache-2.0 require keeping the notices; the ArtCraft brand terms allow naming the origin in
/// plain text).
pub fn about_attribution(ui: &mut Ui, lang: &str) {
    let tk = Tokens::get(ui.ctx());
    if let Some(tex) = png_texture(ui.ctx(), "freeandiy-seal", SEAL_PNG) {
        ui.add(egui::Image::new(&tex).fit_to_exact_size(egui::vec2(56.0, 56.0)));
    }
    let text = t(lang, ATTRIBUTION).replace("{app}", APP_NAME).replace("{upstream}", UPSTREAM_NAME);
    ui.label(egui::RichText::new(text).size(11.0).color(tk.text_dim));
    ui.label(egui::RichText::new(format!("© {OWNER}")).size(11.0).color(tk.text_dim));
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_marks_decode() {
        let ctx = Context::default();
        assert!(png_texture(&ctx, "seal", SEAL_PNG).is_some());
        assert!(png_texture(&ctx, "mark", MARK_PNG).is_some());
    }

    #[test]
    fn light_and_dark_are_paper_and_ink() {
        assert_eq!(Tokens::for_brightness(Brightness::Light).panel, PAPER);
        assert_eq!(Tokens::for_brightness(Brightness::Dark).app_bar, BLACK);
        assert_eq!(Tokens::for_brightness(Brightness::Light).radius, 0);
    }
}
